export function count(e,t,o=`${t}s`){return`${e} ${e===1?t:o}`}export function welcomeLine(e){const t=e.dueToday+e.overdue;return t>0?`Welcome back. ${count(t,"follow-up")} ${t===1?"is":"are"} waiting for you today.`:e.upcoming>0?`Welcome back. The desk is clear today, and ${count(e.upcoming,"event")} ${e.upcoming===1?"is":"are"} on the calendar this week.`:e.applications>0?"Welcome back. The desk is clear today.":"Welcome back. The office is ready whenever you are."}export function pageTitle(e,t){const o=t.dueToday+t.overdue;return o>0?`(${o}) ${e}`:e}export function storageNote(e,t){switch(e){case"unavailable":return"This browser is not letting the office save, so anything you enter will be gone when the tab closes. A private window is the usual reason.";case"newer":return"Your office was saved by a newer version of this page, so it has been left exactly as it was. Reloading the page should open it.";case"unreadable":return"The saved office could not be read, so it has been left untouched and nothing will be saved over it.";default:return t&&t.warn?"Your office is using most of the space this browser allows. Saving a backup soon would be wise.":""}}export function clockTime(e){const t=e.getHours(),o=String(e.getMinutes()).padStart(2,"0");return`${t%12===0?12:t%12}:${o} ${t<12?"AM":"PM"}`}export function dayStartLine(e){return`A day is going by at the window, starting from ${clockTime(e)}. Stop the day ends it whenever you like.`}export function dayEndLine(e,t){return t?`A whole day has gone by. It is ${clockTime(e)} again.`:`Back to the present. It is ${clockTime(e)}.`}
